        move = input("Enter your move (e.g. A1): ").upper()
        if len(move) != 2 or move[0] not in 'ABC' or move[1] not in '123':
            print("Invalid move. Please enter a two-letter combination representing a cell.")
        else:
            return move

# Function to make a random computer move
